    dame: { m: ['libertades', 'libertad'], t: 'Libertades', d: 'Los puntos vacíos junto a un grupo (arriba, abajo, izquierda, derecha). Si se llenan todos, el grupo es capturado.' },
    shimari: { m: ['cierre', 'Cerrar'], t: 'Cierre (shimari)', d: 'Una segunda piedra junto a tu piedra de esquina para asegurarla.' },
    kakari: { m: ['aproximación', 'Aproximarse'], t: 'Aproximación (kakari)', d: 'Una jugada junto a la piedra de esquina rival que le impide cerrar.' },
    sansan: { m: ['3-3'], t: 'Punto 3-3', d: 'El punto a tres líneas de ambos bordes: toma el territorio de la esquina en una jugada.' },
    tengen: { m: ['tengen'], t: 'Tengen', d: 'El punto central del tablero.' },
    atsumi: { m: ['grosor'], t: 'Grosor', d: 'Un muro fuerte de piedras mirando hacia fuera, sin peligro de captura: ayuda a atacar y a formar marcos.' },
    ko: { m: ['ko'], t: 'Ko', d: 'Una forma en la que una piedra puede capturarse de un lado a otro. No se puede recapturar enseguida: antes hay que jugar una amenaza.' },
