  'f.win': 'ganhando', 'f.big': 'claramente melhor', 'f.adv': 'melhor', 'f.sl': 'um pouco melhor', 'f.even': 'igual', 'f.sld': 'um pouco pior', 'f.dis': 'pior', 'f.bad': 'claramente pior', 'f.lost': 'perdendo',
