  'fk.sanrensei': 'Sanrensei', 'fk.nirensei': 'Nirensei', 'fk.chinese': 'Chinesa', 'fk.hchinese': 'Chinesa alta', 'fk.tasuki': 'Diagonal', 'fk.tengen': 'Abertura tengen', 'fk.54': 'Ponto 5-4', 'fk.33': 'Ponto 3-3',
